package dev.rodrigosambade.chat;
import dev.rodrigosambade.net.ConnectivityAndInternetAccess;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.time.Duration;
public final class ChatClient implements AutoCloseable{private final Socket socket;private final BufferedReader in;private final BufferedWriter out;public ChatClient(String host,int port,String nick)throws IOException{ConnectivityAndInternetAccess.requireInternetForRemoteHost(host,Duration.ofSeconds(2));socket=new Socket();socket.connect(new InetSocketAddress(host,port),3000);in=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.UTF_8));out=new BufferedWriter(new OutputStreamWriter(socket.getOutputStream(),StandardCharsets.UTF_8));sendRaw("NICK "+nick);String answer=in.readLine();if(!"OK".equals(answer)){close();throw new IOException(answer);}}public void sendMessage(String msg)throws IOException{if(msg.contains("\n")||msg.contains("\r"))throw new IllegalArgumentException("single line");sendRaw("MSG "+msg);}public String readEvent()throws IOException{return in.readLine();}private void sendRaw(String l)throws IOException{out.write(l);out.newLine();out.flush();}@Override public void close()throws IOException{try{if(!socket.isClosed())sendRaw("QUIT");}catch(IOException ignored){}socket.close();}public static void main(String[]a)throws Exception{if(a.length<3)throw new IllegalArgumentException("host port nick");try(var c=new ChatClient(a[0],Integer.parseInt(a[1]),a[2]);var console=new BufferedReader(new InputStreamReader(System.in,StandardCharsets.UTF_8))){Thread reader=Thread.ofPlatform().start(()->{try{for(String e;(e=c.readEvent())!=null;)System.out.println(e);}catch(IOException ignored){}});for(String l;(l=console.readLine())!=null&&!l.equalsIgnoreCase("/quit");)c.sendMessage(l);reader.interrupt();}}}
